class P {
    toString(): string {
        return "P!";
    }
}

class V {
    valueOf(): number {
        return 5;
    }
    toString(): string {
        return "v";
    }
}

class Q {
    [Symbol.toPrimitive](hint: string): any {
        return hint === "number" ? 7 : "Q:" + hint;
    }
}

async function main(): Promise<void> {
    const p = new P();
    console.log(`${p}`, String(p), "" + p, p + "");
    const v = new V();
    console.log(`${v}`, String(v), v + 1);
    const q = new Q();
    console.log(`${q}`, String(q), q + "", +q);
}
